-- Auth tables for the self-hosted (Postgres) release. To become a migration; assumes `workspaces(id text)` exists.
-- Times are timestamptz. Ids are opaque text generated by the app (usr_...).

CREATE TABLE users (
  id            text PRIMARY KEY,
  -- Stored lowercased by the app; the check keeps the unique constraint case-insensitive.
  email         text NOT NULL UNIQUE CHECK (email = lower(email)),
  name          text,
  -- 'scrypt$<logN>$<r>$<p>$<salt>$<hash>', or NULL for users who only sign in with OIDC.
  password_hash text,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- OIDC identities. Users are matched by (issuer, subject), never by email.
CREATE TABLE user_identities (
  issuer     text NOT NULL,
  subject    text NOT NULL,
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- Email the provider reported when the identity was linked (informational).
  email      text,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (issuer, subject)
);
CREATE INDEX user_identities_user_id ON user_identities (user_id);

-- Only the SHA-256 (hex) of the cookie token is stored.
CREATE TABLE sessions (
  token_hash text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  renewed_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_id ON sessions (user_id);
CREATE INDEX sessions_expires_at ON sessions (expires_at);

CREATE TABLE workspace_members (
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role         text NOT NULL CHECK (role IN ('owner', 'member')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, user_id)
);
-- "Which workspaces is this user in" (GET /api/me, /api/workspaces). The primary key covers lookups by workspace.
CREATE INDEX workspace_members_user_id ON workspace_members (user_id);
